# segments.py
"""保存剪辑素材的名称与时长。"""


class Segment:
    """一段可修订时长的素材，单位为整秒。"""

    def __init__(self, title):
        self.title = title
        self.seconds = 0

    def set_length(self, seconds):
        if seconds < 0:
            raise ValueError("时长不能为负")
        self.seconds = seconds

    def extend(self, extra):
        if extra < 0:
            raise ValueError("补录不能为负")
        self.set_length(self.seconds + extra)

    def label(self):
        return f"{self.title}｜{self.seconds} 秒"


if __name__ == "__main__":
    intro = Segment("片头")
    outro = Segment("片尾")
    intro.set_length(12)
    intro.extend(3)
    intro.title = "新版片头"
    print(intro.label())
    print(outro.label())
    try:
        intro.extend(-1)
    except ValueError as error:
        print(error, intro.seconds)

