"""带字幕的素材及其字幕轨。"""
from segments import Segment


class CaptionTrack:
    """保存一条字幕轨上非空的文字。"""

    def __init__(self):
        self.lines = []

    def add(self, text):
        if text.strip():
            self.lines.append(text.strip())


class CaptionedSegment(Segment):
    """在基础素材标签后标明字幕条数。"""

    def __init__(self, title):
        super().__init__(title)
        self.track = CaptionTrack()

    def label(self):
        return f"{super().label()}｜字幕 {len(self.track.lines)} 条"


if __name__ == "__main__":
    first = CaptionedSegment("采访")
    second = CaptionedSegment("片尾")
    first.extend(5)
    first.track.add(" 开场 ")
    first.track.add("  ")
    print(first.label())
    print(second.label())

from random import choice, randint


def pick_checkpoint(durations):
    ready = [title for title, seconds in durations.items() if seconds > 0]
    if not ready:
        return None
    title = choice(ready)
    return title, randint(1, durations[title])


